INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 0, 10118, 2, 40, "フリーマーケット会場", "青空の下で謁見", 20063115, 2834, 1, 5118061, 7, 91002, 8, "ペコリーヌとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 0, 10118, 2, 40, "フリーマーケット会場", "未来の騎空団\nマスコット？", 20063115, 2835, 1, 5118062, 7, 91002, 8, "マホとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 0, 10118, 2, 40, "ランドソル市街地", "お嬢さまからの\n緊急依頼", 20063115, 2837, 1, 5118063, 7, 91002, 8, "アキノとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 0, 10118, 2, 40, "フリーマーケット会場", "黄金色の悩みごと", 20063115, 4108402, 1, 5118064, 18, 91002, 8, "ジュンとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 0, 10118, 2, 40, "フリーマーケット会場", "白熱！　格闘大会！", 20063115, 4107402, 1, 5118065, 18, 91002, 8, "カオリとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 1, 10118, 2, 40, "オーエド町", "祭り太鼓はオーエドの華", 20063115, 9000227, 1, 5118066, 16, 91002, 8, "ニノンとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 0, 10118, 3, 40, "フリーマーケット会場", "人気者は遅れて\nやってくる", 20063115, 2101181, 1, 5118067, 19, 91002, 8, "スズナとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 0, 10118, 3, 40, "ランドソル市街地", "巫女・ミーツ・魔法少女", 20063115, 4109402, 1, 5118068, 18, 91002, 8, "ナナカとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 0, 10118, 3, 40, "フリーマーケット会場", "ネズ耳は二度なくなる", 20063115, 4305402, 1, 5118069, 18, 91002, 8, "キャル＆コッコロとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 0, 10118, 3, 40, "ランドソル市街地", "この出会いにカンパイ！", 20063115, 4101402, 1, 5118070, 18, 91002, 8, "ユカリとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 0, 10118, 3, 40, "ランドソル市街地", "陰陽アンサンブル", 20063115, 4106402, 1, 5118071, 18, 91002, 8, "アオイとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 1, 10118, 3, 40, "フリーマーケット会場", "運試し十番勝負！", 20063115, 2836, 1, 5118072, 7, 91002, 8, "シノブとの出会い");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (0, 0, 10118, 1, 0, 0, "彼女たちの新たな日常", 20063115, 0, 0, 5118600, 0, 0, 0, "オープニング");
